void GRPC_TO_TURBOLINK(const ::nightfall::v1::EntitySpawn* in, FGrpcNightfallV1EntitySpawn* out)
{
    out->EntityId=StringCast<TCHAR>((const UTF8CHAR*)(in->entity_id().c_str())).Get();
    out->Name=StringCast<TCHAR>((const UTF8CHAR*)(in->name().c_str())).Get();
    out->HasPosition = in->has_position();
    out->Position = {};
    if (out->HasPosition) GRPC_TO_TURBOLINK(&(in->position()), &(out->Position));
    out->Kind=[](int value) { switch (value) { case 0: case 1: case 2: return StaticCast<EGrpcNightfallV1EntityKind>(value); default: return EGrpcNightfallV1EntityKind::ENTITY_KIND_UNSPECIFIED; } }(static_cast<int>(in->kind()));
    out->SessionGeneration=in->session_generation();
    out->Combatant=in->combatant();
    out->TemplateId=StringCast<TCHAR>((const UTF8CHAR*)(in->template_id().c_str())).Get();
    out->LifeIncarnation=in->life_incarnation();
    out->Dead=in->dead();
    out->Attackable=in->attackable();
    out->Hp=in->hp();
    out->MaxHp=in->max_hp();
    out->Level=in->level();
    {
        FGrpcNightfallV1AttackStarted field;
        GRPC_TO_TURBOLINK(&(in->pending_swing()), &field);
        out->PendingSwing = MakeShareable(new FGrpcNightfallV1AttackStarted(field));
    }
    out->Race=[](int value) { switch (value) { case 0: case 1: case 2: case 3: case 4: case 5: return StaticCast<EGrpcNightfallV1Race>(value); default: return EGrpcNightfallV1Race::RACE_UNSPECIFIED; } }(static_cast<int>(in->race()));
    out->ClassId=in->class_id();
    out->Sex=[](int value) { switch (value) { case 0: case 1: case 2: return StaticCast<EGrpcNightfallV1Sex>(value); default: return EGrpcNightfallV1Sex::SEX_UNSPECIFIED; } }(static_cast<int>(in->sex()));
    out->HairStyle=in->hair_style();
    out->HairColor=in->hair_color();
    out->Face=in->face();
    out->StateTick=in->state_tick();
    out->FlagUntilTick=in->flag_until_tick();
    out->Karma=in->karma();
    out->ActiveEffects.Empty();
    for (int i=0; i<in->active_effects_size(); ++i) {
        FGrpcNightfallV1ActiveEffect field;
        GRPC_TO_TURBOLINK(&(in->active_effects(i)), &field);
        out->ActiveEffects.Add(MakeShareable(new FGrpcNightfallV1ActiveEffect(field)));
    }
    {
        FGrpcNightfallV1SkillCastStarted field;
        GRPC_TO_TURBOLINK(&(in->pending_cast()), &field);
        out->PendingCast = MakeShareable(new FGrpcNightfallV1SkillCastStarted(field));
    }
    out->PkCount=in->pk_count();
    out->PvpCount=in->pvp_count();
    out->StatusFlags=in->status_flags();
}

void TURBOLINK_TO_GRPC(const FGrpcNightfallV1EntitySpawn* in, ::nightfall::v1::EntitySpawn* out)
{
    out->set_entity_id((const char*)StringCast<UTF8CHAR>(*(in->EntityId)).Get());
    out->set_name((const char*)StringCast<UTF8CHAR>(*(in->Name)).Get());
    if (in->HasPosition) TURBOLINK_TO_GRPC(&(in->Position), out->mutable_position());
    else out->clear_position();
    out->set_kind(::nightfall::v1::EntityKind(static_cast<uint8>(in->Kind)));
    out->set_session_generation(in->SessionGeneration);
    out->set_combatant(in->Combatant);
    out->set_template_id((const char*)StringCast<UTF8CHAR>(*(in->TemplateId)).Get());
    out->set_life_incarnation(in->LifeIncarnation);
    out->set_dead(in->Dead);
    out->set_attackable(in->Attackable);
    out->set_hp(in->Hp);
    out->set_max_hp(in->MaxHp);
    out->set_level(in->Level);
    TURBOLINK_TO_GRPC(in->PendingSwing.Get(), out->mutable_pending_swing());
    out->set_race(::nightfall::v1::Race(static_cast<uint8>(in->Race)));
    out->set_class_id(in->ClassId);
    out->set_sex(::nightfall::v1::Sex(static_cast<uint8>(in->Sex)));
    out->set_hair_style(in->HairStyle);
    out->set_hair_color(in->HairColor);
    out->set_face(in->Face);
    out->set_state_tick(in->StateTick);
    out->set_flag_until_tick(in->FlagUntilTick);
    out->set_karma(in->Karma);
    for(const auto& value : in->ActiveEffects) {
        TURBOLINK_TO_GRPC(value.Get(), out->add_active_effects());
    }
    TURBOLINK_TO_GRPC(in->PendingCast.Get(), out->mutable_pending_cast());
    out->set_pk_count(in->PkCount);
    out->set_pvp_count(in->PvpCount);
    out->set_status_flags(in->StatusFlags);
}

